describe('Concurrent API Calls', () => {
    beforeEach(() => {
        cy.intercept('GET', '/api/data1', { fixture: 'data1.json' }).as('getData1');
        cy.intercept('GET', '/api/data2', { fixture: 'data2.json' }).as('getData2');
        cy.visit('/'); // Adjust the URL to your application's entry point
    });

    it('should display data after multiple concurrent API calls resolve', () => {
        cy.wait(['@getData1', '@getData2']);
        cy.get('.data-display').should('contain', 'Expected Data from API 1');
        cy.get('.data-display').should('contain', 'Expected Data from API 2');
    });

    it('should handle failure of one API call gracefully', () => {
        cy.intercept('GET', '/api/data2', { statusCode: 500 }).as('getData2Error');
        cy.wait(['@getData1', '@getData2Error']);
        cy.get('.data-display').should('contain', 'Expected Data from API 1');
        cy.get('.error-message').should('be.visible').and('contain', 'Error loading data from API 2');
    });
});
